package scala.tools.nsc;

public final class MainGenericRunner {
  private MainGenericRunner() {}

  public static void main(String[] args) throws Exception {
    String bootclasspath = System.getProperty("scala.test.bootclasspath");
    if (bootclasspath != null) {
      System.setProperty("sun.boot.class.path", bootclasspath);
    }
    String nativepath = System.getProperty("scala.test.nativepath");
    if (nativepath != null) {
      String oldNativepath = System.getProperty("java.library.path", "");
      System.setProperty("java.library.path", nativepath + java.io.File.pathSeparator + oldNativepath);
      try {
        java.lang.reflect.Field sysPaths = ClassLoader.class.getDeclaredField("sys_paths");
        sysPaths.setAccessible(true);
        sysPaths.set(null, null);
      } catch (NoSuchFieldException ignored) {
      }
    }
    if (args.length > 0) {
      try {
        String[] testArgs = new String[args.length - 1];
        System.arraycopy(args, 1, testArgs, 0, testArgs.length);
        Class testClass = Class.forName(args[0]);
        testClass.getMethod("main", new Class[] { String[].class }).invoke(null, new Object[] { testArgs });
        return;
      } catch (NoSuchMethodException directRunFailed) {
        // Fall back to the real runner for non-object invocations.
      }
    }
    Class runnerModuleClass = Class.forName("scala.tools.nsc.MainGenericRunner$");
    Object runnerModule = runnerModuleClass.getField("MODULE$").get(null);
    runnerModuleClass.getMethod("main", new Class[] { String[].class }).invoke(runnerModule, new Object[] { args });
  }
}
